import csv
import io
from typing import Any


def parse_csv(raw_csv: str) -> Any:
    try:
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=";", quotechar='"'))
    except csv.Error:
        records = []

    records = [row for row in records if row and any(value.strip() for value in row)]
    if not records:
        return {"columns": [], "rows": []}

    width = 4
    header_index = next(
        (i for i, row in enumerate(records) if len(row) == width),
        0,
    )

    columns = records[header_index]

    def fit_width(row):
        if len(row) < width:
            return row + [""] * (width - len(row))
        if len(row) > width:
            return row[:width - 1] + [";".join(row[width - 1:])]
        return row

    columns = fit_width(columns)
    rows = [fit_width(row) for row in records[header_index + 1:]]
    return {"columns": columns, "rows": rows}
